import sys as _prompt_sys
from pathlib import Path as _PromptPath
for _prompt_parent in _PromptPath(__file__).resolve().parents:
    if (_prompt_parent / 'runtime_prompt_loader.py').is_file():
        if str(_prompt_parent) not in _prompt_sys.path:
            _prompt_sys.path.insert(0, str(_prompt_parent))
        break
from runtime_prompt_loader import get_prompt as _get_prompt
import os
import json
from datetime import datetime
import psycopg2
from psycopg2.extras import RealDictCursor
from openpyxl import Workbook
PG_HOST = os.getenv('PG_HOST', '127.0.0.1')
PG_PORT = int(os.getenv('PG_PORT', '5433'))
PG_DB = os.getenv('PG_DB', 'mimiciv')
PG_USER = os.getenv('PG_USER', 'postgres')
PG_PWD = os.getenv('PG_PWD', '')
N_SAMPLE = 300
OUT_XLSX = 'non_aki_info.xlsx'
BLOCK_HOURS = 12
CELL_MAX_CHARS = 16000

def to_cell_str(val) -> str:
    """Convert dict/list/jsonb, etc. into strings suitable for writing to Excel, and perform length protection."""
    if val is None:
        return ''
    if isinstance(val, (dict, list)):
        s = json.dumps(val, ensure_ascii=False)
    else:
        s = str(val)
    if len(s) > CELL_MAX_CHARS:
        s = s[:CELL_MAX_CHARS] + '...(truncated)'
    return s

def main():
    conn = psycopg2.connect(host=PG_HOST, port=PG_PORT, dbname=PG_DB, user=PG_USER, password=PG_PWD)
    sql = f"WITH\n    -- ========= 1) Define the AKI groups to be excluded (exclusion logic) =========\n    -- Exclusion list A: stay_id with aki_stage_smoothed >= 1 at any time in KDIGO\n    excluded_kdigo AS (\n      SELECT DISTINCT stay_id\n      FROM mimiciv_derived.kdigo_stages\n      WHERE aki_stage_smoothed >= 1\n    ),\n\n    -- Exclusion list B: hadm_id with ICD diagnosis containing AKI (584% / N17%)\n    excluded_icd AS (\n      SELECT DISTINCT hadm_id\n      FROM mimiciv_hosp.diagnoses_icd\n      WHERE\n        (icd_version = 9 AND icd_code LIKE '584%')\n        OR\n        (icd_version = 10 AND icd_code LIKE 'N17%')\n    ),\n\n    -- ========= 2) Screening Non-AKI patients =========\n    params AS (\n      SELECT ie.stay_id\n      FROM mimiciv_icu.icustays ie\n      WHERE\n        -- EXCLUDE KDIGO AKI\n        ie.stay_id NOT IN (SELECT stay_id FROM excluded_kdigo)\n        -- Exclude ICD AKI\n        AND ie.hadm_id NOT IN (SELECT hadm_id FROM excluded_icd)\n        -- ICU duration >= 24h (maintain original logic)\n        AND ie.outtime >= ie.intime + INTERVAL '24 hour'\n      ORDER BY random()\n      LIMIT{N_SAMPLE}),\n\n    -- ========= 3) ICU basic information =========\n    icu AS (\n      SELECT\n        ie.subject_id, ie.hadm_id, ie.stay_id,\n        ie.intime AS icu_intime,\n        ie.outtime AS icu_outtime,\n        ie.first_careunit, ie.last_careunit\n      FROM mimiciv_icu.icustays ie\n      JOIN params p ON p.stay_id = ie.stay_id\n    ),\n\n    -- ========= 4) Window: Admission to ICU -> 48 hours after admission to ICU =========\n    -- Note: Join aki_onset_detail is no longer here, but manually construct the window and empty indicator\n    win AS (\n      SELECT\n        icu.subject_id,\n        icu.hadm_id,\n        icu.stay_id,\n        icu.icu_intime,\n        icu.icu_outtime,\n        icu.first_careunit,\n        icu.last_careunit,\n\n        --Corresponds to the AKI diagnosis time of the original code. Non-AKI patients do not have this concept. Leave it blank or set to the end time.\n        NULL::timestamp AS aki_detect_time,\n        0 AS aki_stage,\n        0 AS aki_stage_smoothed,\n\n        --Specific indicators at the AKI Onset moment in the original code are all left blank (NULL) here to maintain column structure compatibility.\n        NULL::numeric AS create,\n        NULL::numeric AS creat_low_past_48hr,\n        NULL::numeric AS creat_low_past_7day,\n        NULL::numeric AS aki_stage_creat,\n        NULL::numeric AS uo_rt_6hr,\n        NULL::numeric AS uo_rt_12hr,\n        NULL::numeric AS uo_rt_24hr,\n        NULL::numeric AS aki_stage_uo,\n        NULL::numeric AS aki_stage_crrt,\n\n        --Start of time window: admission to ICU\n        icu.icu_intime AS t_start,\n        --End point of time window: Take the smaller value of (ICU admission+48 hours) and (ICU discharge time)\n        LEAST(icu.icu_outtime, icu.icu_intime + INTERVAL '48 hour') AS t_end\n      FROM icu\n    ),\n\n    -- ========= 5) Half a day per line: 12-hour blocks (logic unchanged) =========\n    win_blocks AS (\n      SELECT\n        w.*,\n        gs.block_start,\n        LEAST(w.t_end, gs.block_start + INTERVAL '{BLOCK_HOURS} hour') AS block_end\n      FROM win w\n      JOIN LATERAL (\n        SELECT generate_series(\n          w.t_start,\n          w.t_end,\n          INTERVAL '{BLOCK_HOURS} hour'\n        ) AS block_start\n      ) gs ON TRUE\n      WHERE LEAST(w.t_end, gs.block_start + INTERVAL '{BLOCK_HOURS}hour') > gs.block_start\n    ),\n\n    -- ========= 6) Various events are aggregated by block (completely maintaining the original logic) =========\n    ce AS (\n      SELECT\n        wb.stay_id,\n        wb.block_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'charttime', ce.charttime,\n            'item_name', di.label,\n            'item_category', di.category,\n            'value', ce.value,\n            'valuenum', ce.valuenum,\n            'valueuom', ce.valueuom,\n            'warning', ce.warning\n          )\n          ORDER BY ce.charttime\n        ) AS chartevents_json\n      FROM win_blocks wb\n      JOIN mimiciv_icu.chartevents ce\n        ON ce.stay_id = wb.stay_id\n      LEFT JOIN mimiciv_icu.d_items di ON di.itemid = ce.itemid\n      WHERE ce.charttime >= wb.block_start AND ce.charttime < wb.block_end\n      GROUP BY wb.stay_id, wb.block_start\n    ),\n\n    le AS (\n      SELECT\n        wb.hadm_id,\n        wb.block_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'charttime', le.charttime,\n            'lab_name', dli.label,\n            'fluid', dli.fluid,\n            'lab_category', dli.category,\n            'value', le.value,\n            'valuenum', le.valuenum,\n            'valueuom', le.valueuom,\n            'ref_range_lower', le.ref_range_lower,\n            'ref_range_upper', le.ref_range_upper,\n            'flag', le.flag,\n            'priority', le.priority\n          )\n          ORDER BY le.charttime\n        ) AS labevents_json\n      FROM win_blocks wb\n      JOIN mimiciv_hosp.labevents le\n        ON le.hadm_id = wb.hadm_id\n      LEFT JOIN mimiciv_hosp.d_labitems dli ON dli.itemid = le.itemid\n      WHERE le.charttime >= wb.block_start AND le.charttime < wb.block_end\n      GROUP BY wb.hadm_id, wb.block_start\n    ),\n\n    ievt AS (\n      SELECT\n        wb.stay_id,\n        wb.block_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'starttime', ie.starttime,\n            'endtime', ie.endtime,\n            'amount', ie.amount,\n            'amountuom', ie.amountuom,\n            'rate', ie.rate,\n            'rateuom', ie.rateuom,\n            'ordercategoryname', ie.ordercategoryname,\n            'ordercategorydescription', ie.ordercategorydescription,\n            'ordercomponenttypedescription', ie.ordercomponenttypedescription,\n            'statusdescription', ie.statusdescription\n          )\n          ORDER BY ie.starttime\n        ) AS inputevents_json\n      FROM win_blocks wb\n      JOIN mimiciv_icu.inputevents ie\n        ON ie.stay_id = wb.stay_id\n      WHERE ie.starttime < wb.block_end AND ie.endtime >= wb.block_start\n      GROUP BY wb.stay_id, wb.block_start\n    ),\n\n    oevt AS (\n      SELECT\n        wb.stay_id,\n        wb.block_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'charttime', oe.charttime,\n            'value', oe.value,\n            'valueuom', oe.valueuom\n          )\n          ORDER BY oe.charttime\n        ) AS outputevents_json\n      FROM win_blocks wb\n      JOIN mimiciv_icu.outputevents oe\n        ON oe.stay_id = wb.stay_id\n      WHERE oe.charttime >= wb.block_start AND oe.charttime < wb.block_end\n      GROUP BY wb.stay_id, wb.block_start\n    ),\n\n    pevt AS (\n      SELECT\n        wb.stay_id,\n        wb.block_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'starttime', pe.starttime,\n            'endtime', pe.endtime,\n            'procedure_name', di.label,\n            'procedure_category', di.category,\n            'value', pe.value,\n            'valueuom', pe.valueuom,\n            'location', pe.location,\n            'locationcategory', pe.locationcategory,\n            'ordercategoryname', pe.ordercategoryname,\n            'ordercategorydescription', pe.ordercategorydescription,\n            'statusdescription', pe.statusdescription\n          )\n          ORDER BY pe.starttime\n        ) AS procedureevents_json\n      FROM win_blocks wb\n      JOIN mimiciv_icu.procedureevents pe\n        ON pe.stay_id = wb.stay_id\n      LEFT JOIN mimiciv_icu.d_items di ON di.itemid = pe.itemid\n      WHERE pe.starttime < wb.block_end AND pe.endtime >= wb.block_start\n      GROUP BY wb.stay_id, wb.block_start\n    ),\n\n    micro AS (\n      SELECT\n        wb.hadm_id,\n        wb.block_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'charttime', COALESCE(me.charttime, me.chartdate),\n            'spec_type_desc', me.spec_type_desc,\n            'test_name', me.test_name,\n            'org_name', me.org_name,\n            'ab_name', me.ab_name,\n            'interpretation', me.interpretation,\n            'quantity', me.quantity\n          )\n          ORDER BY COALESCE(me.charttime, me.chartdate)\n        ) AS microbiology_json\n      FROM win_blocks wb\n      JOIN mimiciv_hosp.microbiologyevents me\n        ON me.hadm_id = wb.hadm_id\n      WHERE COALESCE(me.charttime, me.chartdate) >= wb.block_start\n        AND COALESCE(me.charttime, me.chartdate) < wb.block_end\n      GROUP BY wb.hadm_id, wb.block_start\n    ),\n\n    rx AS (\n      SELECT\n        wb.hadm_id,\n        wb.block_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'starttime', pr.starttime,\n            'stoptime', pr.stoptime,\n            'drug', pr.drug,\n            'route', pr.route,\n            'dose_val_rx', pr.dose_val_rx,\n            'dose_unit_rx', pr.dose_unit_rx,\n            'doses_per_24_hrs', pr.doses_per_24_hrs\n          )\n          ORDER BY pr.starttime\n        ) AS prescriptions_json\n      FROM win_blocks wb\n      JOIN mimiciv_hosp.prescriptions pr\n        ON pr.hadm_id = wb.hadm_id\n      WHERE pr.starttime < wb.block_end AND pr.stoptime >= wb.block_start\n      GROUP BY wb.hadm_id, wb.block_start\n    ),\n\n    pharm AS (\n      SELECT\n        wb.hadm_id,\n        wb.block_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'starttime', ph.starttime,\n            'stoptime', ph.stoptime,\n            'medication', ph.medication,\n            'route', ph.route,\n            'frequency', ph.frequency,\n            'status', ph.status\n          )\n          ORDER BY ph.starttime\n        ) AS pharmacy_json\n      FROM win_blocks wb\n      JOIN mimiciv_hosp.pharmacy ph\n        ON ph.hadm_id = wb.hadm_id\n      WHERE ph.starttime < wb.block_end AND ph.stoptime >= wb.block_start\n      GROUP BY wb.hadm_id, wb.block_start\n    ),\n\n    emar AS (\n      SELECT\n        wb.hadm_id,\n        wb.block_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'charttime', e.charttime,\n            'scheduletime', e.scheduletime,\n            'medication', e.medication,\n            'event_txt', e.event_txt\n          )\n          ORDER BY e.charttime\n        ) AS emar_json\n      FROM win_blocks wb\n      JOIN mimiciv_hosp.emar e\n        ON e.hadm_id = wb.hadm_id\n      WHERE e.charttime >= wb.block_start AND e.charttime < wb.block_end\n      GROUP BY wb.hadm_id, wb.block_start\n    ),\n\n    px AS (\n      SELECT\n        wb.hadm_id,\n        wb.block_start,\n        jsonb_agg(\n          jsonb_build_object('chartdate', pi.chartdate, 'long_title', dip.long_title)\n          ORDER BY pi.chartdate\n        ) AS procedures_text_json\n      FROM win_blocks wb\n      JOIN mimiciv_hosp.procedures_icd pi\n        ON pi.hadm_id = wb.hadm_id\n      LEFT JOIN mimiciv_hosp.d_icd_procedures dip\n        ON dip.icd_code = pi.icd_code AND dip.icd_version = pi.icd_version\n      WHERE dip.long_title IS NOT NULL\n      GROUP BY wb.hadm_id, wb.block_start\n    )\n\n    SELECT\n      -- Primary key column\n      wb.subject_id,\n      wb.hadm_id,\n      wb.stay_id,\n\n      -- ICU time/department\n      wb.icu_intime,\n      wb.icu_outtime,\n      wb.first_careunit,\n      wb.last_careunit,\n\n      -- General window: Admission to ICU -> Admission to ICU+48h\n      wb.t_start,\n      wb.aki_detect_time AS aki_detect_time, -- NULL for Non-AKI\n      wb.t_end AS window_end_time,\n\n      -- Half a day per line: current block\n      wb.block_start AS block_start,\n      wb.block_end AS block_end,\n\n      -- KDIGO onset indicator (Non-AKI is 0 or NULL)\n      wb.aki_stage,\n      wb.aki_stage_smoothed,\n      wb.creat,\n      wb.creat_low_past_48hr,\n      wb.creat_low_past_7day,\n      wb.aki_stage_creat,\n      wb.uo_rt_6hr,\n      wb.uo_rt_12hr,\n      wb.uo_rt_24hr,\n      wb.aki_stage_uo,\n      wb.aki_stage_crrt,\n\n      -- ICD Side AKI Diagnosis (should be empty here as we have excluded people with AKI on ICD)\n      '[]'::jsonb AS aki_icd_json,\n\n      -- Various events (aggregated by half day)\n      COALESCE(ce.chartevents_json, '[]'::jsonb) AS chartevents_json,\n      COALESCE(le.labevents_json, '[]'::jsonb) AS labevents_json,\n      COALESCE(ievt.inputevents_json, '[]'::jsonb) AS inputevents_json,\n      COALESCE(oevt.outputevents_json, '[]'::jsonb) AS outputevents_json,\n      COALESCE(pevt.procedureevents_json, '[]'::jsonb) AS procedureevents_json,\n      COALESCE(micro.microbiology_json, '[]'::jsonb) AS microbiology_json,\n      COALESCE(rx.prescriptions_json, '[]'::jsonb) AS prescriptions_json,\n      COALESCE(pharm.pharmacy_json, '[]'::jsonb) AS pharmacy_json,\n      COALESCE(emar.emar_json, '[]'::jsonb) AS emar_json,\n      COALESCE(px.procedures_text_json, '[]'::jsonb) AS procedures_text_json\n\n    FROM win_blocks wb\n    -- Comment out the Join of aki_icd_detail, because theoretically there should be no match after exclusion\n    -- LEFT JOIN aki_icd_detail aid ON aid.hadm_id = wb.hadm_id\n\n    LEFT JOIN ce ON ce.stay_id = wb.stay_id AND ce.block_start = wb.block_start\n    LEFT JOIN le ON le.hadm_id = wb.hadm_id AND le.block_start = wb.block_start\n    LEFT JOIN ievt ON ievt.stay_id = wb.stay_id AND ievt.block_start = wb.block_start\n    LEFT JOIN oevt ON oevt.stay_id = wb.stay_id AND oevt.block_start = wb.block_start\n    LEFT JOIN pevt ON pevt.stay_id = wb.stay_id AND pevt.block_start = wb.block_start\n    LEFT JOIN micro ON micro.hadm_id = wb.hadm_id AND micro.block_start = wb.block_start\n    LEFT JOIN rx ON rx.hadm_id = wb.hadm_id AND rx.block_start = wb.block_start\n    LEFT JOIN pharm ON pharm.hadm_id = wb.hadm_id AND pharm.block_start = wb.block_start\n    LEFT JOIN emar ON emar.hadm_id = wb.hadm_id AND emar.block_start = wb.block_start\n    LEFT JOIN px ON px.hadm_id = wb.hadm_id AND px.block_start = wb.block_start\n\n    ORDER BY wb.stay_id, wb.block_start;"
    print(_get_prompt('experiments/public_mimic/data_extraction/get_no_aki_info.py::inline_L437', locals()))
    with conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(sql)
        rows = cur.fetchall()
    print(f'>>> SQL query completed, return{len(rows)}records')
    conn.close()
    wb = Workbook(write_only=True)
    ws = wb.create_sheet('non_aki_llm')
    if not rows:
        ws.append(['no rows returned'])
        wb.save(OUT_XLSX)
        print(f'Saved: {OUT_XLSX} (empty result)')
        return
    headers = list(rows[0].keys())
    ws.append(headers)
    total = len(rows)
    print('>>> Start writing to Excel...')
    for i, r in enumerate(rows, start=1):
        ws.append([to_cell_str(r.get(h)) for h in headers])
        if i % 100 == 0:
            print(f'Writing progress:{i}/{total} ({i / total:.0%})')
    wb.save(OUT_XLSX)
    print(f'>>> Done! Saved files:{OUT_XLSX}')
if __name__ == '__main__':
    main()
